import type { BlockEditing } from "@/components/blocks/relume/block-editing";
import type { HOME_PAGE_QUERY_RESULT, PAGE_QUERY_RESULT } from "@/sanity.types";
import { stegaClean } from "next-sanity";
import type { BlockSceneProps } from "../block-boundaries";
import RelumeGallery24Client from "./gallery24.client";

type PageBlock =
  | NonNullable<NonNullable<HOME_PAGE_QUERY_RESULT>["blocks"]>[number]
  | NonNullable<NonNullable<PAGE_QUERY_RESULT>["blocks"]>[number];

type RelumeGallery24Block = Extract<PageBlock, { _type: "relumeGallery24" }>;

export type RelumeGallery24Props = RelumeGallery24Block & {
  editing?: BlockEditing;
} & BlockSceneProps;

// The Page Builder excludes blocks without content from visible adjacency.
// Keep this rule aligned with the renderer's empty result below.
export function hasRelumeGallery24Content(
  block: Pick<RelumeGallery24Block, "heading">,
) {
  return Boolean(stegaClean(block.heading)?.trim());
}

// The block runs in the browser, so it is drawn by a Client Component.
// This entry stays on the server for the content rule above, and passes on
// only what can cross to the browser: `editing` in place of the
// `dataAttribute` function.
export default function RelumeGallery24({
  _key,
  bottom,
  editing,
  heading,
  description,
  images,
  theme,
  top,
}: RelumeGallery24Props) {
  if (!hasRelumeGallery24Content({ heading })) return null;

  return (
    <RelumeGallery24Client
      _key={_key}
      bottom={bottom}
      editing={editing}
      heading={heading}
      description={description}
      images={images}
      theme={theme}
      top={top}
    />
  );
}
